package com.worldgenv2.graph;

import com.worldgenv2.positions.PositionsProvider;
import com.worldgenv2.vector.Vec3d;

import java.util.List;
import java.util.Objects;

/**
 * Places nodes in the graph at 3D coordinates generated by a {@link PositionsProvider}.
 */
public final class PositionsGraphPass implements GraphPass {

    private final PositionsProvider positions;
    private final ContentSupplier contentSupplier;

    public PositionsGraphPass(PositionsProvider positions, ContentSupplier contentSupplier) {
        this.positions = Objects.requireNonNull(positions, "positions");
        this.contentSupplier = contentSupplier != null ? contentSupplier : (n, s) -> GraphContent.EMPTY;
    }

    @Override
    public void execute(ProceduralGraph graph, long seed, GraphBounds bounds) {
        List<Vec3d> points = positions.getPositions(
            bounds.minX(), bounds.minY(), bounds.minZ(),
            bounds.maxX(), bounds.maxY(), bounds.maxZ()
        );

        for (Vec3d pt : points) {
            if (bounds.contains(pt)) {
                GraphNode node = graph.addNode(pt, GraphContent.EMPTY);
                node.setContent(contentSupplier.supply(node, seed));
            }
        }
    }

    public PositionsProvider getPositions() {
        return positions;
    }

    public ContentSupplier getContentSupplier() {
        return contentSupplier;
    }
}
